export const s12ZoologyHi: Record<string, { stem: string; options: string[]; explanation: string }> = {
  "s12zo-b-001": { stem: "आसंजन, रक्षा और शिकार पकड़ने में प्रयुक्त दंश कोशिकाएँ (निडोब्लास्ट) किस संघ की विशेषता हैं?", options: ["पोरीफेरा", "टीनोफोरा", "नाइडेरिया", "प्लेटीहेल्मिंथीज़"], explanation: "स्पर्शकों और शरीर पर दंश कोशिकाएँ नाइडेरिया (सीलेंटरेटा) का निर्धारक लक्षण हैं। टीनोफोरों में ये नहीं होतीं, उनमें कंकत पट्टिकाएँ होती हैं।" },
  "s12zo-b-002": { stem: "जल नाल तंत्र, जिसमें स्पंजगुहा और नालों को कीप कोशिकाएँ (कॉलर कोशिकाएँ) आस्तरित करती हैं, किस संघ की विशेषता है?", options: ["नाइडेरिया", "पोरीफेरा", "इकाइनोडर्मेटा", "ऐनेलिडा"], explanation: "स्पंज (पोरीफेरा) ऑस्टिया से जल भीतर लेते हैं और ऑस्कुलम से बाहर निकालते हैं; कीप कोशिकाएँ स्पंजगुहा और नालों को आस्तरित करती हैं। इकाइनोडर्मों का जल संवहनी तंत्र भिन्न संरचना है।" },
  "s12zo-b-003": { stem: "परासरण नियमन और उत्सर्जन में सहायक ज्वाला कोशिकाएँ पाई जाती हैं:", options: ["प्लेटीहेल्मिंथीज़ में", "ऐनेलिडा में", "ऐस्केल्मिंथीज़ में", "मोलस्का में"], explanation: "प्लेनेरिया और टीनिया जैसे चपटे कृमियों में विशिष्ट ज्वाला कोशिकाएँ (आदिवृक्कक) होती हैं। ऐनेलिड वृक्ककों द्वारा उत्सर्जन करते हैं।" },
  "s12zo-b-004": { stem: "निम्नलिखित में से कौन-सा प्राणी कूटगुहिक (स्यूडोसीलोमेट) है?", options: ["फेरेटिमा (केंचुआ)", "टीनिया (फीताकृमि)", "पाइला (सेब घोंघा)", "एस्कैरिस (गोलकृमि)"], explanation: "एस्कैरिस जैसे ऐस्केल्मिंथीज़ में देहगुहा मध्यजनस्तर से पूर्णतः आस्तरित नहीं होती (कूटगुहा)। टीनिया अगुहिक है; फेरेटिमा और पाइला प्रगुहिक हैं।" },
  "s12zo-b-005": { stem: "गमन, भोजन पकड़ने और श्वसन में सहायक जल संवहनी तंत्र किस संघ का विशिष्ट लक्षण है?", options: ["मोलस्का", "हेमीकॉर्डेटा", "आर्थ्रोपोडा", "इकाइनोडर्मेटा"], explanation: "नाल पादों युक्त जल संवहनी तंत्र केवल ऐस्टेरियस (तारा मछली) जैसे इकाइनोडर्मों में होता है।" },
  "s12zo-b-006": { stem: "कौन-से तीन लक्षण सभी कॉर्डेटों में जीवन की किसी न किसी अवस्था में उपस्थित होते हैं?", options: ["पृष्ठरज्जु, अधर ठोस तंत्रिका रज्जु और युग्मित पख", "पृष्ठरज्जु, पृष्ठीय खोखली तंत्रिका रज्जु और ग्रसनी क्लोम छिद्र", "कशेरुक दंड, अधर हृदय और बंद परिसंचरण", "कशेरुक दंड, जबड़े और युग्मित पाद"], explanation: "पृष्ठरज्जु, पृष्ठीय खोखली तंत्रिका रज्जु और युग्मित ग्रसनी क्लोम छिद्र कॉर्डेटा को परिभाषित करते हैं। कशेरुक दंड केवल कशेरुकियों में होता है, प्रोटोकॉर्डेटों में नहीं।" },
  "s12zo-b-007": { stem: "निम्नलिखित में से कौन-सी उपास्थिल मछली (वर्ग कॉन्ड्रिक्थीज़) है?", options: ["लेबियो रोहिता (रोहू)", "स्कोलियोडॉन (डॉगफ़िश)", "कतला कतला (कतला)", "हिप्पोकैम्पस (समुद्री घोड़ा)"], explanation: "स्कोलियोडॉन में उपास्थिल अंतःकंकाल, प्लेकॉइड शल्क और प्रच्छद रहित क्लोम छिद्र होते हैं। रोहू, कतला और समुद्री घोड़ा अस्थिल मछलियाँ (ऑस्टिक्थीज़) हैं।" },
  "s12zo-b-008": { stem: "निम्नलिखित में से कौन-सा स्तनधारी अंडे देता है?", options: ["मैक्रोपस (कंगारू)", "टेरोपस (उड़न लोमड़ी)", "ऑर्निथोरिंकस (प्लैटिपस)", "बैलीनोप्टेरा (नीली ह्वेल)"], explanation: "प्लैटिपस अंडज मोनोट्रीम है। कंगारू थैलीयुक्त मार्सुपियल है; चमगादड़ और ह्वेल जरायुज अपरायुक्त स्तनधारी हैं।" },
  "s12zo-b-009": { stem: "एक प्राणी में वास्तविक देहगुहा, विखंडीय खंडीभवन, बंद परिसंचरण तंत्र और उत्सर्जन हेतु वृक्कक हैं। यह किस संघ का है?", options: ["प्लेटीहेल्मिंथीज़", "ऐनेलिडा", "आर्थ्रोपोडा", "मोलस्का"], explanation: "ये केंचुए जैसे ऐनेलिडों के लक्षण हैं। आर्थ्रोपोड खंडित होते हैं पर उनमें खुला परिसंचरण तंत्र तथा मैलपीगी नलिकाएँ या हरित ग्रंथियाँ होती हैं।" },
  "s12zo-b-010": { stem: "हीमोलिम्फ से नाइट्रोजनी अपशिष्ट हटाने वाली मैलपीगी नलिकाएँ किसके उत्सर्जी अंग हैं?", options: ["केंचुआ", "प्लेनेरिया", "कॉकरोच", "मेंढक"], explanation: "मैलपीगी नलिकाएँ कॉकरोच जैसे कीटों में होती हैं। केंचुआ वृक्ककों, प्लेनेरिया ज्वाला कोशिकाओं और मेंढक वृक्कों का उपयोग करता है।" },
  "s12zo-p-001": { stem: "अभिकथन (A): टीनोफोरों को सामान्यतः कंकत जेली (कॉम्ब जेली) कहा जाता है।\nकारण (R): इनमें आठ बाह्य पंक्तियों में पक्ष्माभी कंकत पट्टिकाएँ होती हैं जो गमन में सहायता करती हैं।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं पर R, A की सही व्याख्या नहीं है", "A सत्य है पर R असत्य है", "A असत्य है पर R सत्य है"], explanation: "पक्ष्माभी कंकत पट्टिकाओं की आठ पंक्तियाँ ही टीनोफोरों (जैसे प्ल्यूरोब्रेकिया) को यह नाम देती हैं, अतः R, A की व्याख्या करता है।" },
  "s12zo-p-002": { stem: "प्राणी को उसके संघ से सुमेलित कीजिए।\nसूची I: A. पाइला, B. ऐस्टेरियस, C. एंकाइलोस्टोमा, D. बैलेनोग्लोसस\nसूची II: 1. इकाइनोडर्मेटा, 2. हेमीकॉर्डेटा, 3. मोलस्का, 4. ऐस्केल्मिंथीज़", options: ["A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-4, B-1, C-3, D-2", "A-3, B-1, C-4, D-2"], explanation: "पाइला (सेब घोंघा) मोलस्क है, ऐस्टेरियस (तारा मछली) इकाइनोडर्म, एंकाइलोस्टोमा (अंकुशकृमि) ऐस्केल्मिंथ और बैलेनोग्लोसस (एकॉर्न कृमि) हेमीकॉर्डेट है।" },
  "s12zo-p-003": { stem: "इन कथनों पर विचार कीजिए। I. स्पंज उभयलिंगी होते हैं और उनमें निषेचन आंतरिक होता है। II. ओबेलिया में पॉलिप और मेड्यूसा रूपों के बीच पीढ़ी एकांतरण (मेटाजेनेसिस) होता है। III. चपटे कृमि अगुहिक होते हैं। IV. इकाइनोडर्मों के लार्वा अरीय सममित होते हैं। कौन-से सही हैं?", options: ["केवल I और II", "केवल I, II और III", "केवल II, III और IV", "I, II, III और IV"], explanation: "कथन I से III मानक पाठ्यपुस्तक तथ्य हैं। IV गलत है: वयस्क इकाइनोडर्म अरीय सममित होते हैं पर उनके लार्वा द्विपार्श्व सममित होते हैं।" },
  "s12zo-p-004": { stem: "ड्यूटेरोस्टोम प्राणियों में ब्लास्टोपोर से गुदा बनती है और देहगुहा आंत्रगुहिक (एंटेरोसीलस) होती है। कौन-सा संघ युग्म ड्यूटेरोस्टोम है?", options: ["ऐनेलिडा और आर्थ्रोपोडा", "मोलस्का और आर्थ्रोपोडा", "इकाइनोडर्मेटा और कॉर्डेटा", "नाइडेरिया और टीनोफोरा"], explanation: "इकाइनोडर्म, हेमीकॉर्डेट और कॉर्डेट ड्यूटेरोस्टोम हैं। ऐनेलिड, आर्थ्रोपोड और मोलस्क प्रोटोस्टोम हैं, और नाइडेरिया तथा टीनोफोरा त्रिस्तरीय प्रगुहिक ही नहीं हैं।" },
  "s12zo-p-005": { stem: "निम्नलिखित में से कौन-सा वर्ग ऐम्फ़िबिया का लक्षण नहीं है?", options: ["दो अलिंद और एक निलय वाला हृदय", "अवस्कर (क्लोएका) की उपस्थिति", "शल्क रहित नम त्वचा", "उल्व (एम्नियॉन) से घिरे अंडे (उल्वी अंडे)"], explanation: "उभयचर अनुल्वी (ऐनैम्निओट) हैं और जल में अंडे देते हैं। उल्व सर्वप्रथम सरीसृपों में आता है, जो पक्षियों और स्तनधारियों के साथ उल्वी प्राणी हैं।" },
  "s12zo-p-006": { stem: "अधिकांश अन्य जीवित सरीसृपों के विपरीत, क्रोकोडाइलस में होता है:", options: ["अपूर्ण निलय पट वाला तीन-कक्षीय हृदय", "चार-कक्षीय हृदय", "नम ग्रंथिल त्वचा", "अवस्कर का अभाव"], explanation: "सरीसृपों में सामान्यतः आंशिक निलय पट वाला तीन-कक्षीय हृदय होता है, पर मगरमच्छ का हृदय पूर्णतः विभाजित, चार-कक्षीय होता है।" },
  "s12zo-p-007": { stem: "चिरभ्रूणता (नियोटेनी), अर्थात् लैंगिक रूप से परिपक्व प्राणी में लार्वा लक्षणों का बने रहना, का शास्त्रीय उदाहरण है:", options: ["इक्थियोफ़िस", "हायला", "ऐम्बिस्टोमा का ऐक्सोलोटल लार्वा", "राना"], explanation: "ऐक्सोलोटल बाह्य क्लोम और लार्वा रूप बनाए रखते हुए प्रजनन करता है। इक्थियोफ़िस पादविहीन उभयचर है तथा हायला और राना में सामान्य कायांतरण होता है।" },
  "s12zo-p-008": { stem: "द्विस्तरीय प्राणी हाइड्रा में बाह्य बाह्यजनस्तर और आंतरिक अंतःजनस्तर एक अविभेदित परत द्वारा पृथक होते हैं जिसे कहते हैं:", options: ["मध्यजनस्तर", "मीसोग्लिया", "देहगुहा", "कूटगुहा"], explanation: "द्विस्तरीय प्राणियों में दोनों जनस्तरों के बीच अकोशिकीय मीसोग्लिया होती है। वास्तविक मध्यजनस्तर केवल त्रिस्तरीय प्राणियों में होता है।" },
  "s12zo-p-009": { stem: "वर्ग को उसके लक्षण से सुमेलित कीजिए।\nसूची I: A. साइक्लोस्टोमेटा, B. ऑस्टिक्थीज़, C. एवीज़, D. मैमेलिया\nसूची II: 1. प्रच्छद (ऑपरकुलम) से ढके क्लोम, 2. जबड़ा रहित, वृत्ताकार चूषक मुख, 3. वक्ष को उदर से पृथक करने वाला डायाफ्राम, 4. आहार नाल में अन्नपुट (क्रॉप) और पेषणी (गिज़र्ड)", options: ["A-2, B-1, C-4, D-3", "A-1, B-2, C-4, D-3", "A-2, B-1, C-3, D-4", "A-4, B-1, C-2, D-3"], explanation: "लैम्प्रे और हैगफ़िश जबड़ा रहित तथा चूषक मुख वाले हैं, अस्थिल मछलियों में प्रच्छद होता है, पक्षियों में अन्नपुट और पेषणी तथा स्तनधारियों में पेशीय डायाफ्राम होता है।" },
  "s12zo-p-010": { stem: "वयस्क की शारीरिक सममिति के आधार पर बेमेल चुनिए:", options: ["ऑरेलिया", "ऐडैम्सिया", "एस्कैरिस", "ऐस्टेरियस"], explanation: "ऑरेलिया (जेलीफ़िश), ऐडैम्सिया (समुद्री ऐनीमोन) और वयस्क ऐस्टेरियस (तारा मछली) अरीय सममित हैं। एस्कैरिस द्विपार्श्व सममित है।" },
  "s12zo-b-011": { stem: "वयस्क मनुष्य के आमाशय में प्रोटीन का पाचन किसकी क्रिया से आरंभ होता है?", options: ["ट्रिप्सिन", "एंटेरोकाइनेज़", "कार्बोक्सीपेप्टिडेज़", "पेप्सिन"], explanation: "मुख्य कोशिकाओं का पेप्सिनोजन HCl द्वारा सक्रिय पेप्सिन में बदलता है, जो प्रोटीनों को प्रोटियोज़ और पेप्टोन में तोड़ता है। ट्रिप्सिन और कार्बोक्सीपेप्टिडेज़ छोटी आंत में कार्य करते हैं।" },
  "s12zo-b-012": { stem: "आंत्र श्लेष्मा द्वारा स्रावित एंटेरोकाइनेज़ बदलता है:", options: ["पेप्सिनोजन को पेप्सिन में", "फ़ाइब्रिनोजन को फ़ाइब्रिन में", "ट्रिप्सिनोजन को ट्रिप्सिन में", "प्रोरेनिन को रेनिन में"], explanation: "एंटेरोकाइनेज़ ट्रिप्सिनोजन को ट्रिप्सिन में सक्रिय करता है, जो फिर अन्य अग्न्याशयी प्रकिण्वों को सक्रिय करता है। पेप्सिनोजन और प्रोरेनिन आमाशय में HCl द्वारा सक्रिय होते हैं।" },
  "s12zo-b-013": { stem: "वयस्क मनुष्य का दंत सूत्र (ऊपरी/निचले जबड़े के प्रत्येक अर्धभाग में कृंतक, रदनक, अग्रचर्वणक, चर्वणक) है:", options: ["2123/2123", "2023/2023", "2133/2133", "2122/2122"], explanation: "प्रत्येक अर्ध जबड़े में 2 कृंतक, 1 रदनक, 2 अग्रचर्वणक और 3 चर्वणक होते हैं, जिससे 8 × 4 = 32 स्थायी दाँत बनते हैं।" },
  "s12zo-b-014": { stem: "मानव रुधिर में अधिकांश ऑक्सीजन (लगभग 97%) का परिवहन होता है:", options: ["प्लाज़्मा में घुलित रूप में", "प्लाज़्मा में बाइकार्बोनेट आयनों के रूप में", "RBC में हीमोग्लोबिन से बंधकर ऑक्सीहीमोग्लोबिन के रूप में", "कार्बामिनोहीमोग्लोबिन के रूप में"], explanation: "लगभग 97% O₂ लाल रुधिर कणिकाओं के हीमोग्लोबिन द्वारा और केवल लगभग 3% प्लाज़्मा में घुलकर जाती है। बाइकार्बोनेट और कार्बामिनोहीमोग्लोबिन CO₂ परिवहन के रूप हैं।" },
  "s12zo-b-015": { stem: "शांत श्वसन के दौरान स्वस्थ वयस्क मनुष्य का ज्वारीय आयतन लगभग होता है:", options: ["1100 mL", "4600 mL", "2500 mL", "500 mL"], explanation: "ज्वारीय आयतन लगभग 500 mL है। निःश्वसन आरक्षित आयतन लगभग 1000–1100 mL और अंतःश्वसन आरक्षित आयतन लगभग 2500–3000 mL है।" },
  "s12zo-b-016": { stem: "मानव हृदय का गति प्रेरक (पेसमेकर), जो प्रति मिनट अधिकतम क्रिया विभव उत्पन्न करता है, है:", options: ["अलिंद-निलय पर्व (AV नोड)", "शिरा-अलिंद पर्व (SA नोड)", "हिस का बंडल", "पुरकिंजे तंतु"], explanation: "दाएँ अलिंद के ऊपरी भाग में स्थित SA नोड प्रत्येक हृदय स्पंदन (लगभग 70–75 प्रति मिनट) आरंभ करता है, अतः यही लय निर्धारित करता है।" },
  "s12zo-b-017": { stem: "सामान्य विद्युत हृद्लेख (ECG) में QRS सम्मिश्र दर्शाता है:", options: ["अलिंदों का विध्रुवण", "निलयों का पुनर्ध्रुवण", "निलयों का विध्रुवण", "अर्धचंद्र कपाटों का बंद होना"], explanation: "P तरंग अलिंद विध्रुवण, QRS सम्मिश्र निलय विध्रुवण और T तरंग निलय पुनर्ध्रुवण है।" },
  "s12zo-b-018": { stem: "प्राणियों का कौन-सा समूह मुख्यतः यूरिकोटेलिक है, अर्थात् नाइट्रोजनी अपशिष्ट यूरिक अम्ल के रूप में उत्सर्जित करता है?", options: ["पक्षी, स्थलीय घोंघे और अधिकांश सरीसृप", "अस्थिल मछलियाँ और टैडपोल", "स्तनधारी और वयस्क मेंढक", "समुद्री उपास्थिल मछलियाँ"], explanation: "यूरिक अम्ल को निकालने में बहुत कम जल लगता है, जो पक्षियों, सरीसृपों, स्थलीय घोंघों और कीटों के अनुकूल है। अस्थिल मछलियाँ अमोनियोटेलिक हैं; स्तनधारी, वयस्क मेंढक और समुद्री उपास्थिल मछलियाँ यूरियोटेलिक हैं।" },
  "s12zo-b-019": { stem: "स्तनधारियों में अमोनिया और CO₂ से ऑर्निथीन चक्र द्वारा यूरिया का संश्लेषण होता है:", options: ["वृक्कों में", "यकृत में", "मूत्राशय में", "अग्न्याशय में"], explanation: "ऑर्निथीन (यूरिया) चक्र यकृत कोशिकाओं में चलता है। वृक्क केवल रुधिर से यूरिया को छानते हैं।" },
  "s12zo-b-020": { stem: "प्रतिमूत्रल हॉर्मोन (ADH, वैसोप्रेसिन) जल का पुनरवशोषण मुख्यतः किस भाग में बढ़ाता है?", options: ["समीपस्थ संवलित नलिका", "हेनले लूप की अवरोही भुजा", "ग्लोमेरुलस", "दूरस्थ संवलित नलिका और संग्राहक वाहिनी"], explanation: "ADH दूरस्थ नलिका और संग्राहक वाहिनी को जल के लिए अधिक पारगम्य बनाता है, जिससे सांद्र मूत्र बनता है। PCT में पुनरवशोषण मुख्यतः ADH से स्वतंत्र है।" },
  "s12zo-b-021": { stem: "कंदुक-खल्लिका (बॉल और सॉकेट) संधि पाई जाती है:", options: ["प्रगंडिका (ह्यूमरस) और अंस मेखला के बीच", "एटलस और एक्सिस के बीच", "अंगूठे की कार्पल और मेटाकार्पल के बीच", "घुटने पर फ़ीमर और टिबिया के बीच"], explanation: "कंधा (प्रगंडिका और अंस मेखला) कंदुक-खल्लिका संधि है। एटलस-एक्सिस धुराग्र संधि, अंगूठे की संधि सैडल संधि और घुटना कब्जा संधि है।" },
  "s12zo-b-022": { stem: "कंकाल पेशी तंतु की संकुचन की क्रियात्मक इकाई, जो दो क्रमागत Z रेखाओं के बीच स्थित होती है, है:", options: ["पेशी तंतुक (मायोफ़ाइब्रिल)", "पूलिका (फ़ैसिकल)", "सार्कोमियर", "सार्कोलेमा"], explanation: "सार्कोमियर पेशी तंतुक का दो Z रेखाओं के बीच का भाग है; इसके छोटा होने से संकुचन होता है। पूलिका पेशी तंतुओं का बंडल है।" },
  "s12zo-b-023": { stem: "कौन-सा हॉर्मोन पश्च पीयूष (न्यूरोहाइपोफ़ाइसिस) से मुक्त होता है?", options: ["प्रोलैक्टिन", "थायरॉइड उद्दीपक हॉर्मोन", "वृद्धि हॉर्मोन", "ऑक्सीटोसिन"], explanation: "ऑक्सीटोसिन और वैसोप्रेसिन हाइपोथैलेमस में बनकर न्यूरोहाइपोफ़ाइसिस से मुक्त होते हैं। प्रोलैक्टिन, TSH और GH अग्र पीयूष से आते हैं।" },
  "s12zo-p-011": { stem: "एक व्यक्ति की हृदय दर 72 स्पंदन प्रति मिनट और प्रवाह आयतन (स्ट्रोक आयतन) 70 mL है। हृद् निकास है:", options: ["1.03 L/min", "5.04 L/min", "7.20 L/min", "4.20 L/min"], explanation: "हृद् निकास = प्रवाह आयतन × हृदय दर = 70 mL × 72/min = 5040 mL/min ≈ 5.04 L/min।" },
  "s12zo-p-012": { stem: "एक व्यक्ति प्रति मिनट 12 बार 500 mL ज्वारीय आयतन से श्वास लेता है। यदि शारीरिक मृत स्थान 150 mL है, तो कूपिका संवातन है:", options: ["6000 mL/min", "1800 mL/min", "7800 mL/min", "4200 mL/min"], explanation: "कूपिका संवातन = (ज्वारीय आयतन − मृत स्थान) × दर = (500 − 150) × 12 = 4200 mL/min। 6000 mL/min कुल फुफ्फुसीय संवातन है।" },
  "s12zo-p-013": { stem: "निम्नलिखित में से कौन ऑक्सीजन-हीमोग्लोबिन वियोजन वक्र को दाईं ओर (कम O₂ बंधुता) खिसकाता है?", options: ["ताप में कमी", "रुधिर pH में वृद्धि", "pCO₂ में वृद्धि", "2,3-BPG स्तर में कमी"], explanation: "उच्च pCO₂, उच्च H⁺ (निम्न pH), उच्च ताप और अधिक 2,3-BPG सभी हीमोग्लोबिन की O₂ बंधुता घटाते हैं (बोर प्रभाव), जिससे ऊतकों में O₂ मुक्त होना सुगम होता है।" },
  "s12zo-p-014": { stem: "दैहिक केशिकाओं में क्लोराइड विस्थापन (हैम्बर्गर परिघटना) का अर्थ है:", options: ["प्लाज़्मा में बाहर जाते HCO₃⁻ के बदले Cl⁻ का RBC में प्रवेश", "HCO₃⁻ के साथ Cl⁻ का RBC से प्लाज़्मा में निकलना", "हेनले लूप की आरोही भुजा में Cl⁻ का पुनरवशोषण", "तंत्रिका कोशिका झिल्ली के पार Na⁺ के बदले Cl⁻ का विनिमय"], explanation: "RBC में कार्बोनिक एनहाइड्रेज़ द्वारा बना HCO₃⁻ प्लाज़्मा में विसरित होता है, और विद्युत उदासीनता बनाए रखने के लिए Cl⁻ भीतर आता है।" },
  "s12zo-p-015": { stem: "इनुलिन स्वतंत्र रूप से छनता है और नेफ्रॉन द्वारा न पुनरवशोषित होता है न स्रावित। यदि प्लाज़्मा इनुलिन 1 mg/mL, मूत्र इनुलिन 125 mg/mL और मूत्र प्रवाह 1 mL/min है, तो ग्लोमेरुलर निस्यंदन दर है:", options: ["1 mL/min", "12.5 mL/min", "125 mL/min", "250 mL/min"], explanation: "GFR = इनुलिन निष्कासन = (U × V)/P = (125 × 1)/1 = 125 mL/min, जो सामान्य मानव मान है।" },
  "s12zo-p-016": { stem: "प्रतिधारा क्रियाविधि में हेनले लूप के बारे में कौन-सा कथन सही है?", options: ["आरोही भुजा जल के लिए अत्यधिक पारगम्य है", "अवरोही भुजा जल के लिए पारगम्य है पर विद्युत अपघट्यों के लिए लगभग अपारगम्य है", "अवरोही भुजा सक्रिय रूप से NaCl बाहर पंप करती है", "आरोही भुजा में ऊपर चढ़ते हुए निस्यंद अधिक सांद्र होता जाता है"], explanation: "अवरोही भुजा से जल अतिपरासारी मध्यांश में निकल जाता है। आरोही भुजा जल के लिए अपारगम्य है पर विद्युत अपघट्यों को बाहर भेजती है, अतः उसका निस्यंद तनु हो जाता है।" },
  "s12zo-p-017": { stem: "अभिकथन (A): पैराथायरॉइड हॉर्मोन की कमी से अपतानिका (टेटनी, पेशियों की सतत ऐंठन) हो सकती है।\nकारण (R): पैराथायरॉइड हॉर्मोन रुधिर में Ca²⁺ का स्तर घटाता है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं पर R, A की सही व्याख्या नहीं है", "A सत्य है पर R असत्य है", "A असत्य है पर R सत्य है"], explanation: "PTH अतिकैल्सियमी है: यह रुधिर Ca²⁺ बढ़ाता है, अतः R असत्य है। इसकी कमी से अल्पकैल्सियमता होती है जो अपतानिका लाती है, अतः A सत्य है।" },
  "s12zo-p-018": { stem: "सर्पी तंतु सिद्धांत के अनुसार, संकुचन के दौरान सार्कोमियर का कौन-सा भाग समान लंबाई का बना रहता है?", options: ["I पट्ट", "H क्षेत्र", "संपूर्ण सार्कोमियर", "A पट्ट"], explanation: "पतले तंतु मोटे तंतुओं पर सरकते हैं, अतः I पट्ट और H क्षेत्र छोटे होते हैं, जबकि A पट्ट (मोटे तंतुओं की लंबाई) स्थिर रहता है।" },
  "s12zo-p-019": { stem: "कंकाल पेशी में सार्कोप्लाज़्मिक जालिका से मुक्त Ca²⁺ ____ से बंधता है, जिससे ऐक्टिन पर मायोसिन-बंधन स्थल अनावृत हो जाते हैं।", options: ["ट्रोपोमायोसिन", "ट्रोपोनिन", "मायोसिन शीर्ष", "कैल्मोडुलिन"], explanation: "Ca²⁺ ट्रोपोनिन की एक उप-इकाई से बंधता है; ट्रोपोनिन-ट्रोपोमायोसिन सम्मिश्र खिसककर ऐक्टिन के सक्रिय स्थल खोल देता है। अरेखित पेशी में यह भूमिका कैल्मोडुलिन निभाता है।" },
  "s12zo-p-020": { stem: "तंत्रिका क्रिया विभव की उठती (विध्रुवण) प्रावस्था मुख्यतः किसके कारण होती है?", options: ["K⁺ का बहिर्वाह", "Cl⁻ का अंतर्वाह", "Na⁺ का अंतर्वाह", "Na⁺/K⁺ पंप द्वारा Na⁺ का बहिर्वाह"], explanation: "उद्दीपन से वोल्टता-नियंत्रित Na⁺ चैनल खुलते हैं और Na⁺ का तीव्र अंतर्वाह भीतरी भाग को धनात्मक कर देता है। K⁺ बहिर्वाह पुनर्ध्रुवण कराता है।" },
  "s12zo-p-021": { stem: "हॉर्मोनी स्थिति को विकार से सुमेलित कीजिए।\nसूची I: A. वयस्कों में थायरॉइड हॉर्मोनों की कमी, B. वयस्कों में वृद्धि हॉर्मोन की अधिकता, C. कॉर्टिसोल की अधिकता, D. ADH की कमी\nसूची II: 1. एक्रोमेगाली, 2. उदकमेह (डायबिटीज़ इन्सिपिडस), 3. मिक्सीडिमा, 4. कुशिंग सिंड्रोम", options: ["A-3, B-1, C-4, D-2", "A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-4, B-1, C-3, D-2"], explanation: "वयस्क अल्पथायरॉइडता से मिक्सीडिमा, वृद्धि रुकने के बाद GH की अधिकता से एक्रोमेगाली, कॉर्टिसोल की अधिकता से कुशिंग सिंड्रोम और ADH की कमी से उदकमेह होता है।" },
  "s12zo-p-022": { stem: "आंत्र श्लेष्मा द्वारा अवशोषित वसा काइलोमाइक्रॉन में बंद होकर सबसे पहले किसमें पहुँचती है?", options: ["अंकुरों की रुधिर केशिकाओं में", "सीधे यकृत निवाहिका शिरा में", "बृहदांत्र की गुहा में", "अंकुरों के आक्षीर वाहिनी (लैक्टियल, लसीका वाहिकाएँ) में"], explanation: "काइलोमाइक्रॉन रुधिर केशिकाओं में जाने के लिए बहुत बड़े होते हैं, अतः वे लैक्टियल में जाकर लसीका द्वारा बाद में रुधिर तक पहुँचते हैं। शर्कराएँ और ऐमीनो अम्ल रुधिर केशिकाओं में जाते हैं।" },
  "s12zo-b-024": { stem: "प्राणी कोशिका का तारककेंद्रक (सेंट्रिओल) बना होता है:", options: ["सूक्ष्मनलिकाओं के नौ परिधीय त्रिकों से, बिना केंद्रीय सूक्ष्मनलिकाओं के", "नौ परिधीय द्विकों और एक केंद्रीय युग्म सूक्ष्मनलिकाओं से", "नौ परिधीय एकलों और एक केंद्रीय युग्म से", "केवल दो केंद्रीय सूक्ष्मनलिकाओं से"], explanation: "तारककेंद्रक में नौ समान दूरी पर स्थित त्रिक सूक्ष्मनलिकाओं का गाड़ी-पहिया विन्यास (9 + 0) होता है। द्विकों का 9 + 2 विन्यास पक्ष्माभ और कशाभ में होता है।" },
  "s12zo-b-025": { stem: "लयनकाय (लाइसोसोम) घिसे-पिटे कोशिकांगों को पचा पाते हैं क्योंकि वे:", options: ["अम्लीय pH पर सक्रिय जल-अपघटनी एंज़ाइम रखते हैं", "ऑक्सीकारी फॉस्फोरिलीकरण द्वारा ATP बनाते हैं", "अपनी सतह पर प्रोटीन संश्लेषित करते हैं", "पेशी संकुचन हेतु कैल्सियम संचित करते हैं"], explanation: "लयनकाय झिल्ली-आबद्ध पुटिकाएँ हैं जिनमें अम्ल हाइड्रोलेज़ (लाइपेज़, प्रोटिएज़, कार्बोहाइड्रेज़) भरपूर होते हैं जो अम्लीय pH पर सर्वाधिक सक्रिय होते हैं।" },
  "s12zo-b-026": { stem: "प्लाज़्मा झिल्ली का व्यापक रूप से स्वीकृत तरल मोज़ेक मॉडल किसने प्रस्तुत किया?", options: ["सिंगर और निकोलसन", "डेनियली और डावसन", "श्लाइडेन और श्वान", "वॉटसन और क्रिक"], explanation: "सिंगर और निकोलसन (1972) ने प्रस्तावित किया कि प्रोटीन अर्ध-तरल लिपिड द्विपरत में तैरते हैं। डेनियली और डावसन ने पहले का सैंडविच मॉडल दिया था।" },
  "s12zo-b-027": { stem: "प्राणी कोशिका में कोशिकाद्रव्य विभाजन (साइटोकाइनेसिस) होता है:", options: ["केंद्र से बाहर की ओर कोशिका पट्ट बनने से", "प्लाज़्मा झिल्ली में भीतर की ओर गहरी होती खाँच (फ़रो) से", "फ़्रैग्मोप्लास्ट बनने से", "मध्य पटलिका के जमाव से"], explanation: "प्राणी कोशिकाओं में विदलन खाँच बनकर गहरी होती जाती है और कोशिका दो में बँट जाती है। कोशिका पट्ट और फ़्रैग्मोप्लास्ट दृढ़ भित्ति वाली पादप कोशिकाओं में बनते हैं।" },
  "s12zo-b-028": { stem: "मनुष्य में डाउन सिंड्रोम का कारण है:", options: ["गुणसूत्र 21 की त्रिसूत्रता", "X गुणसूत्र की एकसूत्रता", "पुरुष में एक अतिरिक्त X गुणसूत्र", "गुणसूत्र 18 की त्रिसूत्रता"], explanation: "गुणसूत्र 21 की एक अतिरिक्त प्रति (47, +21) से डाउन सिंड्रोम होता है। X एकसूत्रता टर्नर सिंड्रोम और XXY क्लाइनफ़ेल्टर सिंड्रोम है।" },
  "s12zo-b-029": { stem: "टर्नर सिंड्रोम वाली स्त्री का कैरियोटाइप है:", options: ["47, XXY", "45, X (44 + XO)", "47, XXX", "47, XY, +21"], explanation: "टर्नर सिंड्रोम एक X गुणसूत्र के अभाव से होता है, जिससे 45 गुणसूत्र (44 + XO) होते हैं। ऐसी स्त्रियाँ अल्पविकसित अंडाशयों के कारण बंध्य होती हैं।" },
  "s12zo-b-030": { stem: "हीमोफ़ीलिया X-सहलग्न अप्रभावी विकार है। एक सामान्य स्त्री, जिसके पिता हीमोफ़ीलिक थे, एक सामान्य पुरुष से विवाह करती है। उनके किसी पुत्र के हीमोफ़ीलिक होने की प्रायिकता है:", options: ["0", "25%", "50%", "100%"], explanation: "स्त्री अवश्य वाहक (XᴴXʰ) है, क्योंकि उसे पिता से Xʰ मिला है। प्रत्येक पुत्र को X माता से मिलता है, अतः अपेक्षित आधे पुत्र हीमोफ़ीलिक होंगे।" },
  "s12zo-b-031": { stem: "मनुष्य में ABO रुधिर वर्ग तंत्र किसका उदाहरण है?", options: ["केवल अपूर्ण प्रभाविता", "बहुजीनी वंशागति", "लिंग-सहलग्न वंशागति", "बहुविकल्पी अलील, जिनमें Iᴬ और Iᴮ सहप्रभावी हैं"], explanation: "एक जीन (I) के तीन अलील Iᴬ, Iᴮ और i होते हैं। Iᴬ और Iᴮ सहप्रभावी हैं (वर्ग AB) और दोनों i पर प्रभावी हैं।" },
  "s12zo-b-032": { stem: "दात्र कोशिका अरक्तता में हीमोग्लोबिन की β-ग्लोबिन शृंखला के छठे स्थान पर वैलीन किस ऐमीनो अम्ल का स्थान लेता है?", options: ["लाइसीन", "ग्लूटैमिक अम्ल", "हिस्टिडीन", "ग्लाइसीन"], explanation: "एक एकल क्षारक प्रतिस्थापन (mRNA कोडॉन GAG से GUG) ग्लूटैमिक अम्ल को वैलीन से बदल देता है, जिससे कम O₂ तनाव पर हीमोग्लोबिन बहुलकित हो जाता है।" },
  "s12zo-b-033": { stem: "फ़ीनाइलकीटोनूरिया, एक जन्मजात उपापचयी त्रुटि जिसमें फ़ीनाइलऐलानीन टायरोसीन में नहीं बदलता, किस रूप में वंशागत होता है?", options: ["X-सहलग्न अप्रभावी लक्षण", "अलिंगसूत्री प्रभावी लक्षण", "अलिंगसूत्री अप्रभावी लक्षण", "Y-सहलग्न लक्षण"], explanation: "PKU अलिंगसूत्री अप्रभावी है; प्रभावित व्यक्तियों में फ़ीनाइलऐलानीन हाइड्रॉक्सिलेज़ एंज़ाइम नहीं होता और फ़ीनाइलपाइरुविक अम्ल संचित होता है।" },
  "s12zo-p-023": { stem: "रुधिर वर्ग A के लिए विषमयुग्मजी एक पुरुष रुधिर वर्ग B के लिए विषमयुग्मजी एक स्त्री से विवाह करता है। उनकी संतान का रुधिर वर्ग O होने की प्रायिकता है:", options: ["0", "1/2", "3/4", "1/4"], explanation: "Iᴬi × Iᴮi से IᴬIᴮ (AB), Iᴬi (A), Iᴮi (B) और ii (O) समान अनुपात में बनते हैं, अतः वर्ग O की प्रायिकता 1/4 है।" },
  "s12zo-p-024": { stem: "एक वर्णांध पुरुष सामान्य वर्ण दृष्टि के लिए समयुग्मजी स्त्री से विवाह करता है। उनकी संतानों के बारे में कौन-सा कथन सही है?", options: ["सभी पुत्रियाँ वाहक हैं और सभी पुत्र सामान्य हैं", "सभी पुत्र वर्णांध हैं और सभी पुत्रियाँ सामान्य हैं", "आधे पुत्र वर्णांध हैं", "सभी संतानें वर्णांध हैं"], explanation: "पिता अपना Xᶜ प्रत्येक पुत्री को (वाहक) और Y प्रत्येक पुत्र को देता है। पुत्रों को माता से सामान्य X मिलता है, अतः वे सामान्य हैं।" },
  "s12zo-p-025": { stem: "जीव को उसकी लिंग निर्धारण क्रियाविधि से सुमेलित कीजिए।\nसूची I: A. टिड्डा, B. पक्षी, C. मनुष्य, D. मधुमक्खी\nसूची II: 1. अगुणित-द्विगुणिता (हैप्लोडिप्लॉयडी), 2. ZW मादा और ZZ नर, 3. XO नर और XX मादा, 4. XY नर और XX मादा", options: ["A-2, B-3, C-4, D-1", "A-3, B-4, C-2, D-1", "A-3, B-2, C-1, D-4", "A-3, B-2, C-4, D-1"], explanation: "टिड्डों में XX-XO, पक्षियों में ZZ-ZW (मादा विषमयुग्मकी), मनुष्यों में XX-XY, और मधुमक्खियों में निषेचित अंडों से मादाएँ तथा अनिषेचित अंडों से अगुणित नर बनते हैं।" },
  "s12zo-p-026": { stem: "कैरियोटाइप 47, XXX वाली स्त्री की कायिक कोशिकाओं में कितने बार पिंड (लिंग क्रोमैटिन पिंड) दिखेंगे?", options: ["0", "1", "2", "3"], explanation: "एक को छोड़कर सभी X गुणसूत्र बार पिंड के रूप में निष्क्रिय होते हैं, अतः बार पिंडों की संख्या = X गुणसूत्रों की संख्या − 1 = 2।" },
  "s12zo-p-027": { stem: "माइटोकॉन्ड्रियल DNA में उत्परिवर्तन से होने वाला विकार सामान्यतः संचरित होता है:", options: ["प्रभावित माता से उसकी सभी संतानों में", "प्रभावित पिता से उसके सभी पुत्रों में", "प्रभावित पिता से उसकी सभी पुत्रियों में", "किसी भी जनक से समान रूप से आधी संतानों में"], explanation: "युग्मनज के माइटोकॉन्ड्रिया अंडाणु से आते हैं, अतः माइटोकॉन्ड्रियल लक्षण मातृक वंशागति दिखाते हैं: प्रभावित माता के पुत्र-पुत्रियाँ प्रभावित होते हैं, पर प्रभावित पुरुष इसे आगे नहीं देते।" },
  "s12zo-p-028": { stem: "एक वंशावली में एक लक्षण हर पीढ़ी में प्रकट होता है। एक अप्रभावित स्त्री से विवाहित प्रभावित पुरुष इसे अपनी सभी पुत्रियों में और किसी भी पुत्र में नहीं देता। वंशागति की सबसे संभावित विधि है:", options: ["अलिंगसूत्री प्रभावी", "अलिंगसूत्री अप्रभावी", "X-सहलग्न प्रभावी", "Y-सहलग्न"], explanation: "पिता अपना X प्रत्येक पुत्री को और Y प्रत्येक पुत्र को देता है। हर पीढ़ी में सभी पुत्रियों में और किसी पुत्र में नहीं जाना X-सहलग्न प्रभावी लक्षण से मेल खाता है।" },
  "s12zo-p-029": { stem: "G₁ में एक मानव द्विगुणित कोशिका में 46 गुणसूत्र और 2C DNA (C = अगुणित DNA मात्रा) है। द्वितीयक शुक्राणुकोशिका में गुणसूत्र संख्या और DNA मात्रा क्या होगी?", options: ["46 गुणसूत्र, 4C", "23 गुणसूत्र, C", "46 गुणसूत्र, 2C", "23 गुणसूत्र, 2C"], explanation: "S प्रावस्था के बाद प्राथमिक शुक्राणुकोशिका में 46 गुणसूत्र और 4C होता है। अर्धसूत्री विभाजन I गुणसूत्र संख्या आधी कर देता है, पर प्रत्येक गुणसूत्र में अब भी दो अर्धगुणसूत्र होते हैं, अतः 23 गुणसूत्र और 2C।" },
  "s12zo-p-030": { stem: "न्यायालयिक और पितृत्व परीक्षण में प्रयुक्त DNA अंगुलिछापन किसमें व्यक्तिगत भिन्नताओं पर आधारित है?", options: ["गृह-व्यवस्था जीनों के एक्सॉनों में", "पुनरावृत्त DNA में परिवर्ती संख्या अग्रानुक्रम पुनरावृत्तियों (VNTR) में", "केवल राइबोसोमी RNA जीनों में", "प्रारंभक मेथियोनीन के कोडॉन में"], explanation: "VNTR (लघु-अनुषंगी) की प्रतियों की संख्या व्यक्तियों में भिन्न होती है और जनकों से वंशागत होती है, जिससे विशिष्ट पट्ट प्रतिरूप मिलता है। कूटन अनुक्रम बहुत संरक्षित होते हैं।" },
  "s12zo-p-031": { stem: "न्यूक्लियोसोम के केंद्र में स्थित हिस्टोन अष्टक बना होता है:", options: ["H2A, H2B, H3 और H4 के दो-दो अणुओं से", "H1, H2A, H3 और H4 के दो-दो अणुओं से", "H3 और H4 के चार-चार अणुओं से", "H1, H2A, H2B और H3 के एक-एक अणु तथा H4 के चार अणुओं से"], explanation: "केंद्रीय अष्टक में H2A, H2B, H3 और H4 के दो-दो अणु होते हैं, जिनके चारों ओर DNA लिपटा होता है। H1 केंद्र के बाहर का संयोजक हिस्टोन है।" },
  "s12zo-p-032": { stem: "अभिकथन (A): हीमोफ़ीलिया स्त्रियों की तुलना में पुरुषों में कहीं अधिक सामान्य है।\nकारण (R): पुरुष X-सहलग्न जीनों के लिए अर्धयुग्मजी होते हैं, अतः उनके X गुणसूत्र पर स्थित एक अप्रभावी अलील भी अभिव्यक्त हो जाता है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं पर R, A की सही व्याख्या नहीं है", "A सत्य है पर R असत्य है", "A असत्य है पर R सत्य है"], explanation: "प्रभावित होने के लिए स्त्री को दो अप्रभावी अलील चाहिए, पर एक X वाला पुरुष एक अलील को ही अभिव्यक्त कर देता है, अतः R, A की व्याख्या करता है।" },
  "s12zo-b-034": { stem: "निम्नलिखित में से कौन-सा संरचना युग्म समजात है, जो अपसारी विकास दर्शाता है?", options: ["तितली और पक्षी के पंख", "ऑक्टोपस और स्तनधारी के नेत्र", "पेंगुइन और डॉल्फ़िन के फ़्लिपर", "ह्वेल, चमगादड़ और मनुष्य के अग्रपाद"], explanation: "कशेरुकी अग्रपादों की मूल अस्थि योजना (प्रगंडिका, बहि:प्रकोष्ठिका-अंत:प्रकोष्ठिका, कार्पल, मेटाकार्पल, अंगुलास्थियाँ) समान है पर कार्य भिन्न हैं। शेष युग्म अभिसारी विकास से बने समवृत्ति अंग हैं।" },
  "s12zo-b-035": { stem: "कालिख से पेड़ों के तने काले होने के बाद औद्योगिक इंग्लैंड में गहरे पंखों वाले पेपर्ड मॉथ (बिस्टन बेटुलेरिया) की वृद्धि किसका उदाहरण है?", options: ["उपार्जित लक्षणों की वंशागति", "पहले से विद्यमान विभिन्नता पर प्राकृतिक वरण", "अंगों का उपयोग और अनुपयोग", "विशेष सृष्टि"], explanation: "गहरे मॉथ पहले से उपस्थित थे; कालिख वाले तनों पर वे शिकारी पक्षियों को कम दिखते थे, अतः अधिक जीवित रहे और प्रजनन किया। यह प्राकृतिक वरण है, लैमार्कीय परिवर्तन नहीं।" },
  "s12zo-b-036": { stem: "पंखों के साथ दाँत और लंबी अस्थिल पूँछ वाला जीवाश्म आर्कियोप्टेरिक्स किनके बीच की संयोजक कड़ी माना जाता है?", options: ["सरीसृप और पक्षी", "मछलियाँ और उभयचर", "उभयचर और सरीसृप", "सरीसृप और स्तनधारी"], explanation: "पर और पंख पक्षी लक्षण हैं, जबकि दाँत, नखरयुक्त अंगुलियाँ और लंबी अस्थिल पूँछ सरीसृपी लक्षण हैं।" },
  "s12zo-b-037": { stem: "गैलापैगोस द्वीपों के डार्विन की फ़िंच, जिनमें एक साझा बीजभक्षी पूर्वज से अनेक प्रकार की चोंचें विकसित हुईं, दर्शाती हैं:", options: ["अभिसारी विकास", "औद्योगिक कृष्णता", "अनुकूली विकिरण", "कृत्रिम वरण"], explanation: "एक पूर्वज से विभिन्न आवासों और आहारों के लिए भिन्न रूपों का विकास अनुकूली विकिरण है। ऑस्ट्रेलियाई मार्सुपियल दूसरा उदाहरण हैं।" },
  "s12zo-b-038": { stem: "छाप (इंप्रिंटिंग), जिसमें नए निकले हंस-शिशु पहली दिखी गतिशील वस्तु के पीछे चलते हैं, का विस्तृत अध्ययन किसने किया?", options: ["इवान पावलोव", "निको टिनबर्जन", "कार्ल वॉन फ़्रिश", "कोनराड लॉरेंज़"], explanation: "कोनराड लॉरेंज़ ने ग्रेलैग हंसों में छाप प्रदर्शित की। पावलोव ने अनुबंधित प्रतिवर्त और वॉन फ़्रिश ने मधुमक्खी नृत्य का अध्ययन किया।" },
  "s12zo-b-039": { stem: "कार्ल वॉन फ़्रिश द्वारा समझाया गया भोजन-संग्राहक मधुमक्खी का वैगल नृत्य अन्य श्रमिकों को बताता है:", options: ["छत्ते से भोजन स्रोत की दिशा और दूरी", "रानी की उपस्थिति", "शिकारी के बारे में चेतावनी", "झुंड बनाने का समय"], explanation: "ऊर्ध्वाधर के सापेक्ष वैगल दौड़ का कोण सूर्य के संदर्भ में दिशा बताता है और उसकी अवधि भोजन स्रोत की दूरी बताती है।" },
  "s12zo-b-040": { stem: "ह्वेल की पीठ पर उगने वाले बार्नेकल लाभान्वित होते हैं, जबकि ह्वेल को न हानि होती है न लाभ। यह पारस्परिक क्रिया है:", options: ["सहोपकारिता", "ऐमेन्सलिज़्म (अंतरजातीय हानि)", "परजीविता", "सहभोजिता"], explanation: "सहभोजिता में एक जाति लाभान्वित (+) और दूसरी अप्रभावित (0) रहती है। सहोपकारिता (+,+), परजीविता (+,−) और ऐमेन्सलिज़्म (−,0) है।" },
  "s12zo-p-033": { stem: "निम्नलिखित में से कौन अलील आवृत्तियों को नहीं बदलता और वास्तव में हार्डी–वाइनबर्ग साम्य की एक शर्त है?", options: ["जीन प्रवाह", "आनुवंशिक विचलन", "बड़ी समष्टि में यादृच्छिक संगम", "उत्परिवर्तन"], explanation: "जीन प्रवाह, आनुवंशिक विचलन, उत्परिवर्तन, पुनर्योजन और प्राकृतिक वरण साम्य को भंग करते हैं। बड़ी समष्टि में यादृच्छिक संगम अलील आवृत्तियों को स्थिर रखता है।" },
  "s12zo-p-034": { stem: "वैज्ञानिक को विचार से सुमेलित कीजिए।\nसूची I: A. लैमार्क, B. डार्विन, C. ह्यूगो डी व्रीज़, D. ओपेरिन और हाल्डेन\nसूची II: 1. ईनोथेरा पर आधारित उत्परिवर्तन सिद्धांत, 2. उपार्जित लक्षणों की वंशागति, 3. प्राकृतिक वरण, 4. जीवन की रासायनिक उत्पत्ति", options: ["A-3, B-2, C-1, D-4", "A-2, B-3, C-1, D-4", "A-2, B-3, C-4, D-1", "A-1, B-3, C-2, D-4"], explanation: "लैमार्क ने उपार्जित लक्षणों की वंशागति, डार्विन ने प्राकृतिक वरण, डी व्रीज़ ने इवनिंग प्रिमरोज़ से उत्परिवर्तन सिद्धांत और ओपेरिन तथा हाल्डेन ने जीवन की रासायनिक उत्पत्ति प्रस्तावित की।" },
  "s12zo-p-035": { stem: "एस. एल. मिलर के 1953 के प्रयोग में ऐमीनो अम्ल बनाने के लिए किस मिश्रण पर विद्युत विसर्जन किया गया?", options: ["CH₄, NH₃, H₂ और जलवाष्प", "CO₂, O₂, N₂ और जलवाष्प", "O₂, H₂S, CO और N₂", "CO₂, NH₃, O₂ और He"], explanation: "मिलर ने मीथेन, अमोनिया, हाइड्रोजन और जलवाष्प वाले, मुक्त ऑक्सीजन रहित अपचायक आदि वायुमंडल का अनुकरण किया और ऐमीनो अम्ल प्राप्त किए।" },
  "s12zo-p-036": { stem: "गॉसे का प्रतिस्पर्धी अपवर्जन सिद्धांत कहता है कि:", options: ["परभक्षी सदैव शिकार समष्टियों को वहन क्षमता से नीचे रखते हैं", "संसाधन असीमित होने पर समष्टियाँ चरघातांकी रूप से बढ़ती हैं", "एक पोषी स्तर से अगले में केवल लगभग 10% ऊर्जा जाती है", "समान सीमित संसाधनों के लिए प्रतिस्पर्धा करने वाली दो निकट संबंधी जातियाँ अनिश्चित काल तक सहअस्तित्व में नहीं रह सकतीं"], explanation: "प्रतिस्पर्धा में कमज़ोर जाति अंततः समाप्त हो जाती है, जब तक कि संसाधन विभाजन सहअस्तित्व संभव न कर दे।" },
  "s12zo-p-037": { stem: "टिनबर्जन के प्रयोगों में क्षेत्रीय नर त्रि-कंटकी स्टिकलबैक यथार्थ मॉडलों की अपेक्षा अपरिष्कृत मॉडलों पर अधिक तत्परता से आक्रमण करते थे, जब अपरिष्कृत मॉडलों में था:", options: ["चाँदी जैसा उदर", "लाल अधोभाग", "नीली आँखें", "बड़ा पृष्ठ पख"], explanation: "प्रतिद्वंद्वी नर का लाल उदर वह संकेत उद्दीपन है जो आक्रामकता के स्थिर क्रिया प्रतिरूप को मुक्त करता है, भले ही मॉडल अपरिष्कृत हो।" },
  "s12zo-p-038": { stem: "कुछ व्यक्ति एक बड़ी समष्टि को छोड़कर एक नई, पृथक बस्ती बसाते हैं। संयोगवश नई समष्टि की अलील आवृत्तियाँ जनक समष्टि से स्पष्ट रूप से भिन्न होती हैं। इसे कहते हैं:", options: ["जीन प्रवाह", "दिशात्मक वरण", "संस्थापक प्रभाव", "स्थायीकारी वरण"], explanation: "संस्थापक प्रभाव आनुवंशिक विचलन का एक रूप है जिसमें संस्थापक जनक जीन कोश का केवल यादृच्छिक नमूना ले जाते हैं।" },
  "s12zo-p-039": { stem: "अभिकथन (A): स्वजन वरण (किन सिलेक्शन) बंध्य श्रमिक मधुमक्खियों के परोपकारी व्यवहार की व्याख्या कर सकता है।\nकारण (R): अगुणित-द्विगुणिता के कारण हाइमेनोप्टेरा में सगी बहनें औसतन अपने तीन-चौथाई जीन साझा करती हैं।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं पर R, A की सही व्याख्या नहीं है", "A सत्य है पर R असत्य है", "A असत्य है पर R सत्य है"], explanation: "श्रमिक अपनी बहनों से (3/4) अपनी संतानों (1/2) की तुलना में अधिक संबंधित होती हैं, अतः रानी को बहनें पालने में सहायता करने से उनके जीन फैलते हैं। R, A की व्याख्या करता है।" },
  "s12zo-p-040": { stem: "ऐलेन के नियम के अनुसार ठंडी जलवायु के स्तनधारियों में गर्म जलवायु के संबंधित रूपों की तुलना में सामान्यतः ____ होते हैं, जिससे ऊष्मा हानि कम होती है।", options: ["लंबे कान और पाद", "छोटे कान और पाद", "अधिक पृष्ठ क्षेत्रफल-आयतन अनुपात", "वसा की पतली परतें"], explanation: "छोटे बाह्यांग खुला पृष्ठ क्षेत्रफल और इस प्रकार ऊष्मा हानि घटाते हैं। मरुस्थलीय स्तनधारियों जैसे लंबे बाह्यांग ऊष्मा निष्कासन में सहायक होते हैं।" },
  "s12zo-b-041": { stem: "शुक्रजनक नलिकाओं में सर्टोली कोशिकाओं का मुख्य कार्य है:", options: ["टेस्टोस्टेरॉन स्रावित करना", "विकसित होती जनन कोशिकाओं को पोषण देना", "समसूत्री विभाजन द्वारा सीधे शुक्राणु बनाना", "शुक्रीय प्लाज़्मा स्रावित करना"], explanation: "सर्टोली कोशिकाएँ जनन कोशिकाओं को पोषण देती हैं। टेस्टोस्टेरॉन अंतराली (लीडिग) कोशिकाएँ स्रावित करती हैं और शुक्रीय प्लाज़्मा सहायक ग्रंथियों से आता है।" },
  "s12zo-b-042": { stem: "मनुष्य में निषेचन सामान्यतः होता है:", options: ["गर्भाशय गुहा में", "गर्भाशय ग्रीवा में", "अंडवाहिनी (फ़ैलोपी नलिका) के तुंबिका (ऐम्पुला) भाग में", "अंडाशय में"], explanation: "अंडाणु और शुक्राणु अंडवाहिनी के तुंबिका भाग में मिलते हैं; युग्मनज फिर विभाजित होते हुए गर्भाशय की ओर जाता है।" },
  "s12zo-b-043": { stem: "मानव भ्रूण गर्भाशय के अंतःस्तर (एंडोमेट्रियम) में किस अवस्था में अंतर्रोपित होता है?", options: ["तूतक (मोरुला)", "युग्मनज", "कंदुक (गैस्ट्रुला)", "कोरकपुटी (ब्लास्टोसिस्ट)"], explanation: "तूतक कोरकपुटी में विकसित होता है, जिसका पोषकोरक अंतःस्तर से चिपकता है; फिर आंतरिक कोशिका समूह भ्रूण बनाता है।" },
  "s12zo-b-044": { stem: "मानव आर्तव चक्र के मध्य में अंडोत्सर्ग किसके तीव्र स्राव (सर्ज) से प्रेरित होता है?", options: ["ल्यूटिनाइज़िंग हॉर्मोन (LH)", "प्रोजेस्टेरॉन", "प्रोलैक्टिन", "ऑक्सीटोसिन"], explanation: "लगभग 14वें दिन LH का तीव्र उभार ग्राफ़ी पुटक को फाड़कर द्वितीयक अंडकोशिका मुक्त कराता है।" },
  "s12zo-b-045": { stem: "व्यावसायिक रेशम का अधिकांश भाग बनाने वाला शहतूती रेशम किसकी इल्ली (कैटरपिलर) द्वारा उत्पन्न होता है?", options: ["ऐन्थेरिया मायलिटा", "बॉम्बिक्स मोराई", "लैसिफ़र लैक्का", "एपिस डॉर्सेटा"], explanation: "बॉम्बिक्स मोराई के लार्वा शहतूत की पत्तियाँ खाकर शहतूती रेशम के कोये बुनते हैं। ऐन्थेरिया मायलिटा से टसर रेशम और लैसिफ़र लैक्का से लाख मिलती है।" },
  "s12zo-b-046": { stem: "मधुमक्खी कॉलोनी में ड्रोन (नर) विकसित होते हैं:", options: ["रॉयल जेली खिलाए गए निषेचित अंडों से", "शहद और पराग खिलाए गए निषेचित अंडों से", "अनिषेचित अंडों से, अनिषेकजनन द्वारा", "श्रमिक मक्खी के निषेचित अंडों से"], explanation: "ड्रोन अगुणित होते हैं और अनिषेचित अंडों से बनते हैं। निषेचित अंडों से मादाएँ बनती हैं: पूरे समय रॉयल जेली मिलने पर रानी, अन्यथा श्रमिक।" },
  "s12zo-b-047": { stem: "निम्नलिखित में से कौन-सी भारतीय प्रमुख कार्प है?", options: ["कॉमन कार्प (साइप्रिनस कार्पियो)", "सिल्वर कार्प (हाइपोफ़्थैल्मिक्थिस मॉलिट्रिक्स)", "ग्रास कार्प (टीनोफ़ैरिंगोडॉन इडेला)", "कतला (कतला कतला)"], explanation: "भारतीय प्रमुख कार्प कतला, रोहू और मृगल हैं। कॉमन, सिल्वर और ग्रास कार्प विदेशी कार्प हैं।" },
  "s12zo-b-048": { stem: "मानव शरीर में प्रतिरक्षी (एंटीबॉडी) किसके द्वारा बनाए जाते हैं?", options: ["B लसीकाणुओं से व्युत्पन्न प्लाज़्मा कोशिकाएँ", "सहायक T लसीकाणु", "न्यूट्रोफ़िल", "लाल रुधिर कणिकाएँ"], explanation: "सक्रिय B लसीकाणु प्लाज़्मा कोशिकाओं में विभेदित होकर प्रतिरक्षी स्रावित करते हैं (तरल प्रतिरक्षा)। T कोशिकाएँ कोशिका-माध्यित प्रतिरक्षा देती हैं।" },
  "s12zo-b-049": { stem: "प्रसव के बाद प्रथम दिनों में स्रावित पीला दूध, खीस (कोलोस्ट्रम), नवजात को निष्क्रिय प्रतिरक्षा मुख्यतः किसकी प्रचुरता से देता है?", options: ["IgE", "IgA", "IgM", "IgD"], explanation: "खीस IgA प्रतिरक्षियों से भरपूर होता है, जो शिशु की आंत की रक्षा करते हैं। IgE एलर्जी से संबंधित है।" },
  "s12zo-b-050": { stem: "निम्नलिखित में से कौन-सा यौन संचारित संक्रमण जीवाणु द्वारा होता है?", options: ["जननिक हर्पीज़", "यकृतशोथ B (हेपेटाइटिस B)", "सिफ़िलिस", "एड्स"], explanation: "सिफ़िलिस ट्रेपोनेमा पैलिडम जीवाणु से होता है। जननिक हर्पीज़, हेपेटाइटिस B और एड्स विषाणु संक्रमण हैं।" },
  "s12zo-p-041": { stem: "100 प्राथमिक शुक्राणुकोशिकाओं से कितने शुक्राणु और 100 प्राथमिक अंडकोशिकाओं से कितने अंडाणु बनते हैं?", options: ["100 और 400", "400 और 400", "200 और 100", "400 और 100"], explanation: "प्रत्येक प्राथमिक शुक्राणुकोशिका चार शुक्राणुप्रसू देती है (400 शुक्राणु)। कोशिकाद्रव्य के असमान विभाजन के कारण प्रत्येक प्राथमिक अंडकोशिका एक अंडाणु और ध्रुवीय पिंड देती है (100 अंडाणु)।" },
  "s12zo-p-042": { stem: "मनुष्य में अंडोत्सर्ग के समय द्वितीयक अंडकोशिका ____ पर रुकी रहती है और शुक्राणु के प्रवेश के बाद ही अर्धसूत्री विभाजन II पूरा करती है।", options: ["प्रोफ़ेज़ I (डिप्लोटीन)", "मेटाफ़ेज़ II", "ऐनाफ़ेज़ I", "टीलोफ़ेज़ II"], explanation: "प्राथमिक अंडकोशिकाएँ भ्रूणीय जीवन से प्रोफ़ेज़ I में रुकी रहती हैं। अंडोत्सर्ग से पहले अर्धसूत्री विभाजन I पूरा होता है और द्वितीयक अंडकोशिका मेटाफ़ेज़ II पर रुकी हुई मुक्त होती है।" },
  "s12zo-p-043": { stem: "शुक्राणुजनन (स्पर्मियोजेनेसिस) के दौरान अग्रपिंडक (एक्रोसोम), जिसमें अंडाणु भेदन में सहायक एंज़ाइम होते हैं, किससे व्युत्पन्न होता है?", options: ["गॉल्जी उपकरण", "माइटोकॉन्ड्रिया", "तारककेंद्रक", "केंद्रक"], explanation: "अग्रपिंडक गॉल्जी पुटिकाओं से बनता है। माइटोकॉन्ड्रिया मध्य भाग का आवरण बनाते हैं और दूरस्थ तारककेंद्रक पूँछ का अक्षीय तंतु बनाता है।" },
  "s12zo-p-044": { stem: "अंडे को उसके विदलन प्रकार से सुमेलित कीजिए।\nसूची I: A. मुर्गी का अंडा, B. कीट का अंडा, C. मेंढक का अंडा, D. समुद्री अर्चिन का अंडा\nसूची II: 1. सतही अंशभंजी, 2. बिंबाभ अंशभंजी, 3. पूर्णभंजी, अल्पपीतकी (समपीतकी) अंडे का, 4. असमान पूर्णभंजी, मध्यपीतकी अंडे का", options: ["A-1, B-2, C-4, D-3", "A-2, B-1, C-3, D-4", "A-2, B-1, C-4, D-3", "A-4, B-1, C-2, D-3"], explanation: "अत्यधिक पीतकयुक्त मुर्गी का अंडा केवल जनन बिंब में विदलित होता है, केंद्रपीतकी कीट अंडा सतही रूप से, मध्यपीतकी मेंढक अंडा असमान पूर्णभंजी तथा अल्पपीतकी समुद्री अर्चिन अंडा पूर्णतः विदलित होता है।" },
  "s12zo-p-045": { stem: "किसी कशेरुकी में संरचनाओं का कौन-सा समूह पूर्णतः मध्यजनस्तर से व्युत्पन्न है?", options: ["मस्तिष्क, मेरुरज्जु और अधिचर्म", "वृक्क, हृदय और कंकाल पेशियाँ", "आहार नाल का आस्तर और यकृत कोशिकाएँ", "नेत्र का लेंस और दंतवल्क (इनेमल)"], explanation: "वृक्क, हृदय, रुधिर और कंकाल पेशियाँ मध्यजनस्तरी हैं। तंत्रिका तंत्र, अधिचर्म, लेंस और दंतवल्क बाह्यजनस्तरी हैं, तथा आहार नाल का आस्तर और यकृत कोशिकाएँ अंतःजनस्तरी हैं।" },
  "s12zo-p-046": { stem: "उभयचर गैस्ट्रुला पर स्पेमान और मैंगोल्ड के प्रयोगों में ब्लास्टोपोर का पृष्ठ ओष्ठ दूसरे भ्रूण में प्रत्यारोपित करने पर द्वितीयक भ्रूण प्रेरित करता था। इस क्षेत्र को कहते हैं:", options: ["तंत्रिका शिखा", "आद्य रेखक (प्रिमिटिव स्ट्रीक)", "प्राथमिक संगठक (स्पेमान संगठक)", "ज़ोना पेल्यूसिडा"], explanation: "पृष्ठ ओष्ठ प्राथमिक संगठक के रूप में तंत्रिका नलिका और अक्षीय संरचनाएँ प्रेरित करता है। आद्य रेखक पक्षी और स्तनधारी भ्रूणों में होता है।" },
  "s12zo-p-047": { stem: "मानव अपरा (प्लेसेंटा) और गर्भावस्था के बारे में कौन-सा कथन सही है?", options: ["अपरा अंतःस्तर को बनाए रखने के लिए FSH स्रावित करती है", "अपरा से ऑक्सीटोसिन गर्भाशय संकुचन रोकता है", "अपरा में माता और भ्रूण का रुधिर स्वतंत्र रूप से मिलता है", "विकसित होती अपरा द्वारा स्रावित hCG प्रारंभिक गर्भावस्था में पीत पिंड (कॉर्पस ल्यूटियम) को बनाए रखता है"], explanation: "hCG प्रारंभिक गर्भावस्था में पीत पिंड से प्रोजेस्टेरॉन स्राव बनाए रखता है। अपरा माता और भ्रूण के रुधिर को अलग रखती है, और ऑक्सीटोसिन (पीयूष से) गर्भाशय संकुचन कराता है, रोकता नहीं।" },
  "s12zo-p-048": { stem: "एड्स रोगी में प्रतिरक्षा का क्रमिक ह्रास मुख्यतः किसके विनाश के कारण होता है?", options: ["सहायक T लसीकाणु (CD4⁺ T कोशिकाएँ)", "B लसीकाणु", "न्यूट्रोफ़िल", "लाल रुधिर कणिकाएँ"], explanation: "HIV महाभक्षकाणुओं में गुणन करके सहायक T कोशिकाओं पर आक्रमण करता है; उनकी संख्या घटने पर तरल और कोशिका-माध्यित दोनों प्रतिरक्षाएँ कमज़ोर हो जाती हैं।" },
  "s12zo-p-049": { stem: "मिश्रित मत्स्य पालन (कंपोज़िट फ़िश कल्चर) में कतला, रोहू और मृगल को एक ही तालाब में मुख्यतः इसलिए डाला जाता है क्योंकि वे:", options: ["परस्पर संकरण करके तीव्र वृद्धि वाले संकर देते हैं", "तालाब के भिन्न स्तरों (सतह, मध्य जल और तल) पर भोजन करते हैं, अतः भोजन के लिए प्रतिस्पर्धा नहीं करते", "सभी तलभक्षी हैं जो तालाब को स्वच्छ रखते हैं", "ऐसे पदार्थ छोड़ते हैं जो एक-दूसरे को रोग से बचाते हैं"], explanation: "कतला सतहभक्षी, रोहू मध्य जलभक्षी और मृगल तलभक्षी है, अतः मिलकर वे बिना प्रतिस्पर्धा के पूरे तालाब के भोजन का उपयोग करती हैं।" },
  "s12zo-p-050": { stem: "अभिकथन (A): रानी बनने वाले मधुमक्खी लार्वा को पूरे लार्वा जीवन में रॉयल जेली खिलाई जाती है।\nकारण (R): रॉयल जेली युवा श्रमिक (धाय) मक्खियों के सिर की ग्रंथियों से स्रावित होती है।", options: ["A और R दोनों सत्य हैं और R, A की सही व्याख्या है", "A और R दोनों सत्य हैं पर R, A की सही व्याख्या नहीं है", "A सत्य है पर R असत्य है", "A असत्य है पर R सत्य है"], explanation: "दोनों कथन सत्य हैं, पर रॉयल जेली का स्रोत यह नहीं बताता कि रानी लार्वा को यह पूरे समय क्यों मिलती है; यही आहार मादा लार्वा को रानी बनाता है।" },
};
